useQuery<SafeUser | null>({
    queryKey: ["/api/auth/user"],
    queryFn: fetchUser,
    retry: false,
    staleTime: 1000 * 60 * 5,
  })

useMutation({
    mutationFn: async (credentials: { email: string; password: string }) => {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(credentials),
      });
      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.message || "Login failed");
      }
      const data = await res.json();
      if (data.mfa_required) {
        return data;
      }
      await queryClient.cancelQueries({queryKey:["/api/auth/user"],exact:true});
      await transitionProtectedActor(data);
      queryClient.setQueryData(["/api/auth/user"], data);
      return data;
    },
    onError: (err: Error) => {
      toast({ title: "Login failed", description: err.message, variant: "destructive" });
    },
  })

useMutation({
    mutationFn: async (data: { code: string; rememberDevice?: boolean }) => {
      const res = await fetch("/api/auth/totp/verify-login", {
        method: "POST",
