        smsBody: editSmsBody,
        sendEmail,
        sendSms,
        callSummary: drafts?.callSummary || "",
        nextSteps: drafts?.nextSteps || "",
        sentiment: drafts?.sentiment || "neutral",
        nextFollowUpDate: values.nextFollowUpDate || undefined,
        interestedIn0Percent: values.interestedIn0Percent,
        needsTerminal: values.needsTerminal,
        sendPacketNow: values.sendPacketNow,
        packetId: values.sendPacketNow && values.packetId !== "auto" ? Number(values.packetId) : undefined,
      });
      return res.json();
    },
    onSuccess: (data,_variables,submitted) => {
      if(selection.current !== submitted?.context) return;
      setSendResult(data);
      setStep("sent");
      queryClient.invalidateQueries({ queryKey: ["/api/deals"] });
      queryClient.invalidateQueries({ queryKey: ["/api/tasks"] });
      queryClient.invalidateQueries({ queryKey: ["/api/call-logs"] });
      const smsCaveat = data.smsResult && data.smsResult !== "sent" && data.smsMessage && data.smsMessage !== "Follow-up SMS was not requested."
        ? ` ${data.smsMessage}`
        : "";
      toast({
        title: "Call logged and follow-ups processed",
        description: `Stage updated to: ${data.newStage || "unchanged"}.${smsCaveat}`,
        variant: data.smsResult === "failed" || data.smsResult === "not_configured" ? "destructive" : undefined,
      });
    },
    onError: (err: Error,_variables,submitted) => {
      if(selection.current !== submitted?.context) return;
      toast({ title: "Failed to send follow-ups", description: err.message, variant: "destructive" });
    },
  })

useCrmQuery<BinResult>({
    queryKey: ["/api/tools/bin-lookup", submittedBin],
    queryFn: async ({signal}) => {
      if (!submittedBin) return { found: false };
      const res = await fetch(`/api/tools/bin-lookup?bin=${encodeURIComponent(submittedBin)}`,{credentials:"include",signal});
      if (!res.ok) {
        const body = await res.json();
        throw new Error(body.message || "Lookup failed");
      }
      const result = await res.json();
      if (!result || typeof result.found !== "boolean") throw new Error("Invalid BIN directory response");
      return result;
    },
    enabled: !!submittedBin && !capability.blocked,
    staleTime: 10 * 60 * 1000,
  })

invalidations.call:
queryClient.invalidateQueries({ predicate: query => {
    const path = String(query.queryKey[0]);
    return workFactFamilies.some(prefix => path.startsWith(prefix));
  } })

queryClient.setQueryData(["/api/contacts", Number(values.contactId), "detail",{section:"deals"},submitted.scope], (old: any) => old
          ? { ...old, deals: old.deals?.map((deal: any) => deal.id === authoritativeDeal.id ? authoritativeDeal : deal) }
          : old)

queryClient.setQueryData<InfiniteData<DealPage, number>>(scopedKey, old => old ? ({
          ...old, pages: old.pages.map(page => ({
            ...page, data: page.data.map(deal => deal.id === variables.id
              ? { ...deal, stage: variables.stage as string } : deal),
          })),
        }) : old)

queryClient.setQueryData<InfiniteData<DealPage, number>>(context.scopedKey, old => old ? ({
          ...old, pages: old.pages.map(page => ({
            ...page, data: page.data.map(deal => deal.id === variables.id ? context.previousDeal! : deal),
          })),
        }) : old)

queryClient.setQueryData<InfiniteData<DealPage, number>>(context.scopedKey, old => old ? ({
            ...old,
            pages: old.pages.map(page => ({
              ...page,
              data: page.data.map(deal => deal.id === authoritativeDeal.id ? authoritativeDeal : deal),
            })),
          }) : old)

qc.setQueryData(queryKey, (old: PaginatedNotifications | undefined) => {
        if (!old) return old;
        return { ...old, data: old.data.map((n) => n.id === id ? { ...n, read: true } : n) };
      })
